title = #{title}, subtitle = #{subtitle}, images = #{images}, description = #{description}, flash_price_cents = #{flashPriceCents}, origin_price_cents = #{originPriceCents}, stock = #{initStock}, sold = #{sold}, limit_per_user = #{limitPerUser}, start_time = #{startTime}, end_time = #{endTime}, status = #{status}, version = version + 1, update_time = CURRENT_TIMESTAMP
